(function (g) {
  'use strict';
  g.OMNI_GAMES = g.OMNI_GAMES || {};
  g.OMNI_GAMES.memory = function (box, api) {
    box.innerHTML =
      '<canvas class="play" id="cv" style="flex:1 1 auto;width:100%"></canvas>' +
      '<div class="btns"><button id="again" class="ghost">重来</button></div>' +
      '<div class="hint" id="hint">点两张，找一样的图案</div>';

    var cv = box.querySelector('#cv'), ctx = cv.getContext('2d');
    var dpr = devicePixelRatio || 1;
    var emojis = ['🍎','🌟','🐱','🐶','🌈','🍭'];
    var cards = [];
    var first = -1, second = -1, lock = false, matched = 0, flips = 0;

    function newGame() {
      cards = [];
      emojis.forEach(function (e) { cards.push({ e: e, open: false, done: false }); cards.push({ e: e, open: false, done: false }); });
      for (var i = cards.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = cards[i]; cards[i] = cards[j]; cards[j] = t; }
      first = second = -1; lock = false; matched = 0; flips = 0;
      box.querySelector('#hint').textContent = '点两张，找一样的图案';
      draw();
    }

    function size() { var r = cv.getBoundingClientRect(); cv.width = r.width * dpr; cv.height = r.height * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
    size(); addEventListener('resize', size);

    function layout() {
      var W = cv.width / dpr, H = cv.height / dpr;
      var cols = 4, rows = 3;
      var pad = Math.min(W, H) * .04;
      var cw = (W - pad * (cols + 1)) / cols;
      var ch = Math.min(cw, (H - pad * (rows + 1)) / rows);
      var totalH = ch * rows + pad * (rows + 1);
      var oy = (H - totalH) / 2;
      return { cols: cols, rows: rows, pad: pad, cw: cw, ch: ch, ox: (W - (cw * cols + pad * (cols - 1))) / 2, oy: oy + pad };
    }

    function draw() {
      var L = layout();
      ctx.clearRect(0, 0, cv.width / dpr, cv.height / dpr);
      cards.forEach(function (c, i) {
        var r = Math.floor(i / L.cols), col = i % L.cols;
        var x = L.ox + col * (L.cw + L.pad);
        var y = L.oy + r * (L.ch + L.pad);
        var radius = Math.min(L.cw, L.ch) * .16;
        ctx.save();
        roundRect(ctx, x, y, L.cw, L.ch, radius);
