        else if (c.open) { ctx.fillStyle = 'rgba(255,255,255,.92)'; ctx.fill(); ctx.strokeStyle = 'rgba(94,231,255,.9)'; }
        else { var grd = ctx.createLinearGradient(x, y, x, y + L.ch); grd.addColorStop(0, '#5ee7ff'); grd.addColorStop(1, '#b388ff'); ctx.fillStyle = grd; ctx.fill(); ctx.strokeStyle = 'rgba(255,255,255,.6)'; }
        ctx.lineWidth = 2; ctx.stroke();
        ctx.font = (Math.min(L.cw, L.ch) * .5) + 'px serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        if (c.open || c.done) ctx.fillText(c.e, x + L.cw / 2, y + L.ch / 2);
        else { ctx.fillStyle = 'rgba(6,17,31,.75)'; ctx.font = 'bold ' + (Math.min(L.cw, L.ch) * .34) + 'px sans-serif'; ctx.fillText('?', x + L.cw / 2, y + L.ch / 2); }
        ctx.restore();
