              a.done = b.done = true; matched++;
              api.gain(2, rect.left + px, rect.top + py, '配对');
              first = second = -1; lock = false; draw();
              if (matched === emojis.length) {
                box.querySelector('#hint').textContent = '全部配对！翻了 ' + flips + ' 次';
