      '<div class="hint" id="hint">拖动接住掉下来的星星</div>';

    var cv = box.querySelector('#cv'), ctx = cv.getContext('2d');
    var dpr = devicePixelRatio || 1;
    var W = 0, H = 0;
    var basketX = 0, targetX = 0, dragging = false;
    var drops = [];
    var score = 0, missed = 0, t0 = performance.now(), lastSpawn = 0;
    var running = true;

    function size() {
      var r = cv.getBoundingClientRect();
      W = r.width; H = r.height;
      cv.width = W * dpr; cv.height = H * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      basketX = W / 2; targetX = W / 2;
    }
    size(); addEventListener('resize', size);

    function spawn() {
      var good = Math.random() > .25;
      drops.push({
        x: 30 + Math.random() * Math.max(1, W - 60),
        y: -20, vy: 1.4 + Math.random() * 1.8,
        good: good,
        r: 12 + Math.random() * 8,
        phase: Math.random() * Math.PI * 2
      });
    }

    function loop() {
      if (!running) return;
      requestAnimationFrame(loop);
      var now = performance.now(), t = (now - t0) / 1000;
      if (now - lastSpawn > 620) { lastSpawn = now; spawn(); }

      basketX += (targetX - basketX) * 0.18;

      ctx.clearRect(0, 0, W, H);
      /* 背景星星 */
      for (var k = 0; k < 20; k++) {
        ctx.globalAlpha = .18;
        ctx.fillStyle = '#dce9ff';
        var px = (k * 79 + t * 8) % W, py = (k * 47) % H;
        ctx.beginPath(); ctx.arc(px, py, 1.6, 0, Math.PI * 2); ctx.fill();
      }
      ctx.globalAlpha = 1;

      /* 掉落物 */
      for (var i = drops.length - 1; i >= 0; i--) {
        var d = drops[i];
        d.y += d.vy;
        if (d.good) {
          ctx.fillStyle = '#ffd166';
          drawStar(ctx, d.x, d.y, d.r, d.r * .45, 5, t * 2 + d.phase);
        } else {
          ctx.fillStyle = '#ff6b81';
          ctx.beginPath(); ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
          ctx.beginPath(); ctx.moveTo(d.x - d.r * .5, d.y - d.r * .5); ctx.lineTo(d.x + d.r * .5, d.y + d.r * .5);
          ctx.moveTo(d.x + d.r * .5, d.y - d.r * .5); ctx.lineTo(d.x - d.r * .5, d.y + d.r * .5); ctx.stroke();
