      gr.addColorStop(0, '#5ee7ff'); gr.addColorStop(1, '#b388ff');
      ctx.fillStyle = gr;
      roundRect(ctx, basketX - bw2 / 2, by2, bw2, bh2, 8); ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,.7)'; ctx.lineWidth = 2; ctx.stroke();
      ctx.restore();
    }
    loop();

    function pos(ev) {
      var r = cv.getBoundingClientRect();
      return ev.clientX - r.left;
    }
    cv.addEventListener('pointerdown', function (ev) { dragging = true; targetX = pos(ev); cv.setPointerCapture && cv.setPointerCapture(ev.pointerId); });
    cv.addEventListener('pointermove', function (ev) { if (dragging) targetX = pos(ev); else targetX = pos(ev); });
    cv.addEventListener('pointerup', function () { dragging = false; });
    cv.addEventListener('pointerleave', function () { dragging = false; });

    function roundRect(c, x, y, w, h, r) { c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r); c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath(); }
    function drawStar(c, cx, cy, R, r, n, rot) {
      c.beginPath();
      for (var i = 0; i < n * 2; i++) {
        var rad = i % 2 === 0 ? R : r;
        var a = rot + i * Math.PI / n - Math.PI / 2;
        var x = cx + Math.cos(a) * rad, y = cy + Math.sin(a) * rad;
        if (i === 0) c.moveTo(x, y); else c.lineTo(x, y);
      }
      c.closePath(); c.fill();
    }
  };
})(window);
