      '<canvas class="play" id="cv" style="flex:1 1 auto;width:100%"></canvas>' +
      '<div class="btns"><button id="again" class="ghost">换一题</button></div>' +
      '<div class="hint" id="hint">把砝码放两边，让天平平衡</div>';

    var cv = box.querySelector('#cv'), ctx = cv.getContext('2d');
    var dpr = devicePixelRatio || 1;
    var W = 0, H = 0;
    var left = [], right = [], pool = [];
    var drag = null, offset = { x: 0, y: 0 };
    var target = 0;
    var solved = false;

    function size() {
      var r = cv.getBoundingClientRect();
      W = r.width; H = r.height;
      cv.width = W * dpr; cv.height = H * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }
