    function newGame() {
      left = []; right = []; pool = []; solved = false;
      var weights = [1, 2, 3, 4, 5, 6];
      for (var i = weights.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = weights[i]; weights[i] = weights[j]; weights[j] = t; }
      /* 左盘放 1-2 块，右盘空，玩家把剩下的分好 */
      var leftCount = 2 + Math.floor(Math.random() * 2);
      for (var k = 0; k < leftCount; k++) left.push({ w: weights[k] });
      for (var k2 = leftCount; k2 < weights.length; k2++) pool.push({ w: weights[k2] });
      var sumL = left.reduce(function (s, x) { return s + x.w; }, 0);
      target = sumL; /* 需要右边凑到 target */
      /* 布局：上部分是托盘，底部是砝码池 */
      var g = Math.min(56, W / 9);
      pool.forEach(function (p, i) {
        p.w2 = g; p.h2 = g;
        var cols = Math.min(8, pool.length);
        var c = i % cols, r = Math.floor(i / cols);
        p.x = 16 + c * (g + 8);
        p.y = H - g - 22 - r * (g + 8);
      });
      box.querySelector('#hint').textContent = '让右边也等于 ' + target;
      draw();
    }

    function roundRect(c, x, y, w, h, r) { c.beginPath(); c.moveTo(x + r, y); c.arcTo(x + w, y, x + w, y + h, r); c.arcTo(x + w, y + h, x, y + h, r); c.arcTo(x, y + h, x, y, r); c.arcTo(x, y, x + w, y, r); c.closePath(); }

    function draw() {
      ctx.clearRect(0, 0, W, H);
      /* 天平基座 */
      var baseY = H * .32;
      var poleX = W / 2;
      ctx.strokeStyle = 'rgba(255,255,255,.75)'; ctx.lineWidth = 6;
