      ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(-beamLen, 0); ctx.lineTo(-beamLen, 40); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(beamLen, 0); ctx.lineTo(beamLen, 40); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(-beamLen, 60, 54, 18, 0, Math.PI, Math.PI * 2); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(beamLen, 60, 54, 18, 0, Math.PI, Math.PI * 2); ctx.stroke();
      ctx.restore();
