      ctx.font = 'bold 18px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      var startX = poleX - beamLen, startY = baseY - 120 + 52;
      left.forEach(function (b, i) {
        var x = startX - 30 + (i % 4) * 22, y = startY - Math.floor(i / 4) * 22;
