        ctx.fillStyle = '#4ade80'; roundRect(ctx, x, y, 26, 22, 6); ctx.fill();
        ctx.fillStyle = '#06111f'; ctx.fillText(b.w, x + 13, y + 11);
      });
      /* 砝码池 */
      pool.forEach(function (p) {
        if (drag === p) return;
        ctx.fillStyle = p.onRight ? '#4ade80' : '#b388ff';
        roundRect(ctx, p.x, p.y, p.w2, p.h2, 10); ctx.fill();
        ctx.fillStyle = '#06111f'; ctx.fillText(p.w, p.x + p.w2 / 2, p.y + p.h2 / 2);
