        var r = cv.getBoundingClientRect();
        api.gain(15, r.left + r.width / 2, r.top + r.height / 2, '平衡了');
        box.querySelector('#hint').textContent = '平衡成功！';
      }
    }

    function pos(ev) { var r = cv.getBoundingClientRect(); return { x: ev.clientX - r.left, y: ev.clientY - r.top }; }
    cv.addEventListener('pointerdown', function (ev) {
      var p = pos(ev);
      for (var i = pool.length - 1; i >= 0; i--) {
        var pc = pool[i];
        if (p.x >= pc.x && p.x <= pc.x + pc.w2 && p.y >= pc.y && p.y <= pc.y + pc.h2) {
          drag = pc;
          offset.x = p.x - pc.x; offset.y = p.y - pc.y;
          api.sfx && api.sfx.pick(); draw(); return;
        }
      }
    });
    cv.addEventListener('pointermove', function (ev) {
      if (!drag) return;
      var p = pos(ev);
      drag.x = p.x - offset.x; drag.y = p.y - offset.y;
      draw();
    });
    cv.addEventListener('pointerup', function (ev) {
      if (!drag) return;
      var cx = drag.x + drag.w2 / 2, cy = drag.y + drag.h2 / 2;
      var poleX = W / 2, baseY = H * .32;
      var beamLen = Math.min(W * .4, 200);
      var startY = baseY - 120 + 52;
      if (cx < poleX && cy < startY + 40) { left.push({ w: drag.w }); pool.splice(pool.indexOf(drag), 1); }
      else if (cx > poleX && cy < startY + 40) { right.push({ w: drag.w }); pool.splice(pool.indexOf(drag), 1); }
      else { drag.x = 16; drag.y = H - drag.h2 - 22; }
      drag = null;
      draw();
    });

